import { Group, Mesh, PlaneGeometry, Color, DoubleSide } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color, texture, vec3, smoothstep, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new Group();
  group.name = 'journal-card-2';

  const palette = (config.intent?.visualSpec?.colors) ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const disposables = [];
  const timelines = [];

  // ---------------------------------------------------------------
  // 1. STAGE BACKDROP — engineered vertical gradient, never flat black.
  // ---------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  const inkColor = color(new Color(palette.ink));
  const surfaceColor = color(new Color(palette.surface));
  backdropMat.colorNode = mix(surfaceColor, inkColor, smoothstep(0.0, 1.0, uv().y));
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  backdrop.renderOrder = -10;
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------------------------------------------------------------
  // 2. ATLAS REGION CARD — sized to source-rect aspect ratio.
  // ---------------------------------------------------------------
  const rect = { x: 0, y: 0, w: 512, h: 320 };
  const atlasSize = { w: rect.w, h: rect.h }; // atlas region == full source image
  const uOffset = rect.x / atlasSize.w;
  const vOffset = 1.0 - (rect.y + rect.h) / atlasSize.h;
  const uScale = rect.w / atlasSize.w;
  const vScale = rect.h / atlasSize.h;

  const cardHeight = 1.9;
  const cardWidth = cardHeight * (rect.w / rect.h);
  const cardGeo = new PlaneGeometry(cardWidth, cardHeight);
  const cardMat = new MeshBasicNodeMaterial({ side: DoubleSide, transparent: true });

  const paperColor = color(new Color(palette.paper));
  const inkTint = color(new Color(palette.ink));

  // Base tinted gradient while texture streams in — engineered surface, not flat.
  cardMat.colorNode = mix(inkTint, paperColor, smoothstep(0.0, 1.0, uv().y));

  const card = new Mesh(cardGeo, cardMat);
  card.position.set(0, 0.15, 0.01);
  group.add(card);
  disposables.push(cardGeo, cardMat);

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.wrapS = THREE.ClampToEdgeWrapping;
    tex.wrapT = THREE.ClampToEdgeWrapping;

    const cardUV = uv().mul(vec3(uScale, vScale, 1.0).xy).add(vec3(uOffset, vOffset, 0.0).xy);
    const grainNode = texture(tex, cardUV);
    const gradientBase = mix(inkTint, paperColor, smoothstep(0.0, 1.0, uv().y));
    // engineered gradient surface modulated by subtle grain, no soft pastel blur
    cardMat.colorNode = mix(gradientBase, gradientBase.mul(grainNode), 0.35);
    cardMat.needsUpdate = true;
  });

  // ---------------------------------------------------------------
  // 3. Thin accent underline — accent used sparingly, <=10% of frame.
  // ---------------------------------------------------------------
  const accentGeo = new PlaneGeometry(cardWidth * 0.4, 0.035);
  const accentMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  accentMat.colorNode = color(new Color(palette.accent));
  const accentStrip = new Mesh(accentGeo, accentMat);
  accentStrip.position.set(-cardWidth * 0.3, 0.15 - cardHeight / 2 - 0.08, 0.02);
  group.add(accentStrip);
  disposables.push(accentGeo, accentMat);

  // ---------------------------------------------------------------
  // 4. Contact shadow plane — grounds the card as a depth plane.
  // ---------------------------------------------------------------
  const shadowGeo = new PlaneGeometry(cardWidth * 1.3, cardHeight * 1.3);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide });
  const distFromCenter = uv().sub(vec3(0.5, 0.5, 0.0).xy).length();
  const falloff = smoothstep(0.5, 0.0, distFromCenter);
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = falloff.mul(0.45);
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, 0.15 - cardHeight * 0.05, -0.05);
  group.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // ---------------------------------------------------------------
  // 5. Static composition — no interactivity, no cinematic primitives.
  // ---------------------------------------------------------------
  group.userData.handlers = {};

  // Applying the specified (empty) primitive list defensively, in case
  // future config revisions attach one.
  const primitiveHandles = [];
  const prims = config.cinematicPrimitives ?? [];
  for (const prim of prims) {
    if (ctx.primitives?.[prim.name]) {
      const handle = ctx.primitives[prim.name](group, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  group.userData.cleanup = () => {
    for (const tl of timelines) {
      tl.kill?.();
    }
    for (const handle of primitiveHandles) {
      handle.cleanup?.();
    }
    for (const res of disposables) {
      res.dispose?.();
    }
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.rotation);
    gsap.killTweensOf(group.scale);
  };

  return group;
}
